import{_ as o,l,o as e,c as n,v as t,p as s,x as i,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"封装用步进器","description":"","frontmatter":{"title":"封装用步进器","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/packaging-steppers.md","filePath":"litho/packaging-steppers.md","lastUpdated":1789023840000}'),c={name:"litho/packaging-steppers.md"};function E(_,a,u,m,A,B){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="封装用步进器" tabindex="-1">封装用步进器 <a class="header-anchor" href="#封装用步进器" aria-label="Permalink to &quot;封装用步进器&quot;">​</a></h1><div class="epigraph"><p>封装步进器买的是大矩形场、长焦深和翘曲行程；NA 故意低，好让厚胶和重建晶圆活在窗口里。</p><footer>—— 对照 packaging stepper（大视场投影）与前道扫描机的规格分工</footer></div><p><a href="/litho/display-litho">上一课</a>给出米级 FPD。缺口是 IC 厂封装线仍用「像步进器的机器」，但规格对着 RDL 而不是 MMP。本课钉封装用步进器。混合键合把对准精度再收紧，留给[下一课](/litho/hybrid-bonding-alignment）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Ultratech/Veeco、Canon、SUSS 一类封装投影：场可达数厘米见方，NA 低，对准行程大，适应翘曲。分辨率典型在微米。与前道 4× 扫描机比：不是同一光学合同，掩模倍率与尺寸也不同。错买高 NA 前道机去印厚胶，DOF 不够；错买封装机去印 M0，分辨率不够。</p><p>缺口是<strong>规格对尺度</strong>，不是品牌。与 LDI 的选择：掩模步进器对重复图形产能好，直写对多品种好——对照无掩模课。</p><h3 id="重建晶圆" tabindex="-1">重建晶圆 <a class="header-anchor" href="#重建晶圆" aria-label="Permalink to &quot;重建晶圆&quot;">​</a></h3><p>Fan-out 重建后芯片位置有统计误差，步进器要对准实测格子，而不是设计直角。面板课的 die shift 在圆片重建上同样存在。</p><p><span class="marginnote">有的「封装扫描机」仍来自前道供应商的衍生平台。看规格表：场、NA、焦深、基板，不要看商标是否眼熟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型矩阵：最小线宽、胶厚、基板、wph、套刻。与前道匹配：凸点对焊盘的套刻预算来自封装机，不是来自 EUV。工厂布局：封装机通常不在同一光刻黄光间等级，颗粒规格不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>低 NA → 大 DOF、低分辨率，正好厚胶。大场 → 少拼接、但畸变要在大场内控。这是投影光学的另一工作点，不是失败的高 NA。</p>',13)),(e(),s(h,null,{default:i(()=>[d(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E5%BE%AE%E7%B1%B3%20%2F%20%E5%8E%9A%E8%83%B6%20%2F%20%E7%BF%98%E6%9B%B2%22%5D%20--%3E%20PKG%5B%22%E5%B0%81%E8%A3%85%E6%AD%A5%E8%BF%9B%E5%99%A8%22%5D%0A%20%20SPEC2%5B%22%E7%BA%B3%E7%B1%B3%20%2F%20%E8%96%84%E8%83%B6%20%2F%20%E5%B9%B3%E7%89%87%22%5D%20--%3E%20FE%5B%22%E5%89%8D%E9%81%93%E6%89%AB%E6%8F%8F%E6%9C%BA%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不给某型号 NA 表当唯一。不把所有 bump 光刻当同一机。下一课键合对准可能用红外，不一定用这台步进器。</p><p>后课默认：RDL 用大视场低 NA；下一课 Cu–Cu 键合对准是另一套精度与传感器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>封装步进器工作点是大场、低 NA、大 DOF，服务厚胶与翘曲。</li><li>与前道机、LDI、FPD 机都不同合同。</li><li>重建晶圆要对实测格子。</li><li>出处：packaging stepper 规格分工通称。</li></ul>',5))])}const D=o(c,[["render",E]]);export{g as __pageData,D as default};
